#!/usr/bin/env python3
import argparse, base64, zlib, hashlib, json
from pathlib import Path
import numpy as np
import pandas as pd
import geopandas as gpd
from pyproj import Transformer
import matplotlib.pyplot as plt

EXPECTED_ID_SHA="a319155b7cec7cf7b9b01611c767f6fbc605250b731bd14574c14fb7caeb48c4"
WWF_CODES_B64=""""""
BIOME={'A':'Boreal Forests/Taiga','B':'Deserts & Xeric Shrublands','C':'Flooded Grasslands & Savannas','D':'Mangroves','E':'Mediterranean Forests, Woodlands & Scrub','F':'Montane Grasslands & Shrublands','G':'Temperate Broadleaf & Mixed Forests','H':'Temperate Conifer Forests','I':'Temperate Grasslands, Savannas & Shrublands','J':'Tropical & Subtropical Coniferous Forests','K':'Tropical & Subtropical Dry Broadleaf Forests','L':'Tropical & Subtropical Grasslands, Savannas & Shrublands','M':'Tropical & Subtropical Moist Broadleaf Forests','N':'Tundra','R':'Rock and Ice'}
TF={'A':('TUNDRA','FOREST'),'B':('DESERT','NONE'),'C':('GRASSLAND','MARSH_CANDIDATE'),'D':('GRASSLAND','MARSH_CANDIDATE'),'E':('PLAINS','FOREST'),'F':('PLAINS','NONE'),'G':('GRASSLAND','FOREST'),'H':('GRASSLAND','FOREST'),'I':('PLAINS','NONE'),'J':('GRASSLAND','FOREST'),'K':('PLAINS','FOREST'),'L':('PLAINS','NONE'),'M':('GRASSLAND','JUNGLE'),'N':('TUNDRA','NONE'),'R':('SNOW','NONE')}

def ensure_lonlat(g):
    if 'lon' in g.columns and 'lat' in g.columns: return g
    c=g.geometry.centroid
    cg=gpd.GeoSeries(c,crs=g.crs).to_crs(4326)
    g=g.copy(); g['lon']=cg.x.to_numpy(); g['lat']=cg.y.to_numpy(); return g

def draw(g,out,title):
    colors={'GRASSLAND':'#7da85b','PLAINS':'#c6b56f','DESERT':'#e5ce8d','TUNDRA':'#a6a893','SNOW':'#edf1f3'}
    fig,ax=plt.subplots(figsize=(18,9),dpi=160)
    for k,c in colors.items():
        s=g[g.TERRAIN==k]
        if len(s): s.plot(ax=ax,color=c,edgecolor='#f4f0df',linewidth=.08)
    ax.set_axis_off(); ax.set_aspect('equal'); ax.set_title(title,fontsize=13)
    plt.tight_layout(); fig.savefig(out,bbox_inches='tight',facecolor='white'); plt.close(fig)

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('stage1b_gpkg'); ap.add_argument('--prefix',default='CIV_GAME_MAP_STAGE2B_BIOMES_HIGHRES_RELIEF_LAND'); a=ap.parse_args()
    g=gpd.read_file(a.stage1b_gpkg,layer='stage1b_land_relief').sort_values('id').reset_index(drop=True)
    if len(g)!=68048 or not g.id.is_unique: raise SystemExit('Stage1B LAND id integrity failure')
    ids=np.asarray(g.id,dtype='<i8')
    h=hashlib.sha256(ids.tobytes()).hexdigest()
    if h!=EXPECTED_ID_SHA: raise SystemExit(f'Canonical LAND ID sequence mismatch: {h}')
    codes=zlib.decompress(base64.b64decode(WWF_CODES_B64)).decode('ascii')
    if len(codes)!=len(g): raise SystemExit('WWF code length mismatch')
    g['WWF_CODE']=list(codes)
    g['WWF_BIOME']=[BIOME[x] for x in codes]
    g['TERRAIN']=[TF[x][0] for x in codes]
    g['FEATURE_ECO']=[TF[x][1] for x in codes]
    rel=g.RELIEF.astype(str).to_numpy()
    eco=g.FEATURE_ECO.astype(str).to_numpy()
    game=np.full(len(g),'NONE',dtype=object)
    for f in ('FOREST','JUNGLE'):
        m=(eco==f)&(rel!='MOUNTAIN'); game[m]=f
    g['FEATURE_GAME']=game
    g['MARSH_CAND']=((eco=='MARSH_CANDIDATE')&(rel!='MOUNTAIN')).astype('int8')
    g['BIO_SRC']='RESOLVE2017_0p5deg_REUSED_CANONICAL_ID'
    g['BIO_STAGE']='STAGE2B_HIGHRES_RELIEF'
    g=ensure_lonlat(g)

    out=a.prefix+'.gpkg'
    g.to_file(out,layer='stage2b_land_biomes',driver='GPKG')
    summ=[]
    for col in ['TERRAIN','RELIEF','FEATURE_ECO','FEATURE_GAME','MARSH_CAND']:
        for k,v in g[col].value_counts(dropna=False).items(): summ.append({'group':col,'class':k,'count':int(v)})
    pd.DataFrame(summ).to_csv(a.prefix+'_SUMMARY.csv',index=False)

    qa_pts=[('Seoul',37.57,126.98,{'GRASSLAND'}),('Tokyo',35.68,139.76,{'GRASSLAND'}),('Amazon',-3.1,-60.0,{'GRASSLAND'}),('Congo',0.5,23.5,{'GRASSLAND'}),('Sahara',24,12,{'DESERT'}),('Arabia',24,45,{'DESERT'}),('Mongolia',46,103,{'PLAINS','DESERT'}),('Siberia',62,100,{'TUNDRA'}),('Greenland',72,-40,{'SNOW','TUNDRA'}),('Sahel',14,0,{'PLAINS'}),('Central_Australia',-24,134,{'DESERT','PLAINS'}),('Patagonia',-47,-70,{'PLAINS','TUNDRA'})]
    la=g.lat.to_numpy(); lo=g.lon.to_numpy(); q=[]
    for name,plat,plon,exp in qa_pts:
        dl=np.abs(lo-plon); dl=np.minimum(dl,360-dl)
        d2=(la-plat)**2+(dl*np.cos(np.deg2rad(plat)))**2; j=int(np.argmin(d2)); r=g.iloc[j]
        q.append({'name':name,'hex_id':int(r.id),'terrain':r.TERRAIN,'feature_eco':r.FEATURE_ECO,'feature_game':r.FEATURE_GAME,'relief':r.RELIEF,'expected_terrain':'/'.join(sorted(exp)),'pass':bool(r.TERRAIN in exp)})
    qdf=pd.DataFrame(q); qdf.to_csv(a.prefix+'_QA.csv',index=False)

    draw(g,a.prefix+'_WORLD_PREVIEW.png','Civilization-style GAME MAP — Stage 2B terrain / biomes with ETOPO2022 60-second relief')
    sa=g[(g.lon>=-85)&(g.lon<=-30)&(g.lat>=-60)&(g.lat<=15)]
    draw(sa,a.prefix+'_SOUTH_AMERICA_PREVIEW.png','Stage 2B — South America terrain / biome QA')
    audit={'land_hexes':len(g),'canonical_id_sha256':h,'qa_pass':int(qdf['pass'].sum()),'qa_total':len(qdf),'source_relief':'ETOPO2022 60 arc-second Stage1B','uses_stage1a_1deg':False,'note':'WWF biome code assignment is preserved by canonical LAND ID from verified Stage2; only relief-dependent game features are recomputed.'}
    Path(a.prefix+'_AUDIT.json').write_text(json.dumps(audit,indent=2),encoding='utf-8')
    print(json.dumps(audit,indent=2))
    print(pd.DataFrame(summ).to_string(index=False))
    print(qdf.to_string(index=False))

if __name__=='__main__': main()
